from pathlib import Path
import json,collections,re,hashlib,sys,shutil
O=Path(sys.argv[1]);tr=json.loads((O/'transaction.json').read_text());S=Path(tr['source_directory']);sha=lambda p:hashlib.sha256(p.read_bytes()).hexdigest();P=O/'hardware/nexus-style-fc.kicad_pcb';SP=S/'hardware/nexus-style-fc.kicad_pcb';g=json.loads((O/'geometry-verification.json').read_text());assert g['source_sha256']==sha(SP)==tr['source_board_sha256'] and g['candidate_sha256']==sha(P)
a,b=[json.loads((x/'native-drc.json').read_text()) for x in [S,O]];assert b['included_severities']==a['included_severities'] and b['ignored_checks']==a['ignored_checks'] and b['kicad_version']==a['kicad_version']=='10.0.7';assert not b['unconnected_items'] and not b['schematic_parity']
sig=lambda z:(z['type'],z['severity'],tuple(sorted(x['uuid'] for x in z['items'])));ca,cb=[collections.Counter(sig(z) for z in d['violations']) for d in [a,b]];assert not cb-ca,('New native violations',list((cb-ca).elements()));wa,wb=[collections.Counter(sig(z) for z in d['violations'] if z['severity']=='warning') for d in [a,b]];assert wa==wb
emap=lambda d:{sig(z):float(re.search(r'actual ([0-9.]+) mm',z['description']).group(1)) for z in d['violations'] if z['severity']=='error' and z['type']=='clearance'};ea,eb=emap(a),emap(b);worse=[{'pair':k,'before_mm':ea[k],'after_mm':eb[k]} for k in set(ea)&set(eb) if eb[k]<ea[k]-.00005];assert not worse,worse;assert ea==eb,('Native clearance pairs/gaps changed during RPM contact transaction',ea,eb);assert not any(z['severity']=='error' and z['type']!='clearance' for z in b['violations'])
# No schematic change in a copper-only batch: carry exact source-native ERC/netlist evidence.
assert sha(S/'hardware/nexus-style-fc.kicad_sch')==sha(O/'hardware/nexus-style-fc.kicad_sch')==tr['source_schematic_sha256']
for name in ['native-erc.json','final-netlist.xml']:
 if (S/name).exists():shutil.copy2(S/name,O/name)
e=json.loads((O/'native-erc.json').read_text());assert not any(x['violations'] for x in e['sheets'])
assert g['pasted_vias_unchanged']['unique_vias']==16 and g['pasted_vias_unchanged']['contact_pairs']==17
diag=json.loads((O/'all-visible/diagnostic-receipt.json').read_text());assert diag['counts']['track_not_centered_on_via']==17 and len(diag['removed_findings'])==1
rpm=json.loads((O/'rpm-return-proof.json').read_text());assert rpm['main_In1_In4_ground_fill_exact']
summary={'status':'ACCEPTED centered full-width RPM donor replacement; native DRC remains unfinished','source_directory':str(S),'source_board_sha256':sha(SP),'candidate_board_sha256':sha(P),'schematic_sha256':sha(O/'hardware/nexus-style-fc.kicad_sch'),'native_drc_sha256':sha(O/'native-drc.json'),'source_clearance_errors':len(ea),'candidate_clearance_errors':len(eb),'unchanged_silk_warnings':sum(wb.values()),'opens':0,'schematic_parity_issues':0,'erc_violations':0,'erc_evidence_basis':'Exact unchanged schematic and source-native ERC receipt; fresh PCB schematic-parity check','minimum_remaining_clearance_mm':min(eb.values()),'worsened_residual_pairs':worse,'removed_native_violation_pairs':list((ca-cb).elements()),'new_native_violation_pairs':[],'geometry_receipt_sha256':sha(O/'geometry-verification.json'),'invariants':g['invariants']['status'],'remaining_inherited_pasted_vias':g['pasted_vias_unchanged'],'all_visible_centering_findings_before':18,'all_visible_centering_findings_after':17,'all_visible_filter_warnings':3,'all_visible_footprint_type_warnings':5,'complete_port_proofs':g['route_physical_proofs'],'rpm_reference_measurements':rpm['measurements'],'main_In1_In4_ground_fill_exact':True,'en_conductive_contacts':g['en_conductive_contacts'],'qualification':'Native unfinished routing checkpoint only. Power/return/thermal, regulator capacitor loops, USB/SI, inherited pasted vias, header/mechanical and fabrication gates remain open.'};(O/'verification.json').write_text(json.dumps(summary,indent=2)+'\n')
print(json.dumps(summary,indent=2))
